        ctx.fillRect(0, Math.max(0, y - bandH), W, bandH * 2);
        ctx.fillStyle = 'rgba(0,240,255,0.5)';
        ctx.fillRect(0, Math.max(0, Math.min(H - 1, y)), W, 1);
